import React, { useRef } from 'react';
import { useMountEffect } from 'primereact/hooks';
import { Messages } from 'primereact/messages';
import { classNames } from 'primereact/utils';

export default function Severity() {
    const msgs = useRef(null);

    useMountEffect(() => {
        if (msgs.current) {
            msgs.current.clear();
            msgs.current.show([
                { sticky: true, className:"info", summary: 'Info', detail: 'Message Content asdasd', closable: false },
                { sticky: true, className:"success", summary: 'Success', detail: 'Message Content', closable: false },
                { sticky: true, className:"warn", summary: 'Warning', detail: 'Message Content', closable: false },
                { sticky: true, className:"error", summary: 'Error', detail: 'Message Content', closable: false },
                { sticky: true, className:"secondary", summary: 'Secondary', detail: 'Message Content', closable: false },
                { sticky: true, className:"contrast", summary: 'Contrast', detail: 'Message Content', closable: false }
            ]);
        }
    });

    return (
        <Messages ref={msgs} />
    )
}